using System.Diagnostics;
using System.IO;
using System.Net.Http;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
namespace CremaTools;

public class ToolSettings { public bool AutoUpdate { get; set; } = true; public string UpdateUrl { get; set; } = "https://raw.githubusercontent.com/thibaud-afk/crematools-updates/main/updates/stable.json"; public string PendingInstaller { get; set; } = ""; public string PendingVersion { get; set; } = ""; public string PendingHash { get; set; } = ""; public DateTime LastCheck { get; set; } = DateTime.MinValue; }
public record UpdatePayload(string Version, string Url, string Sha256, long Size);
public record SignedUpdate(string Payload, string Signature);
public static class UpdateEngine
{
    public static string Version => Assembly.GetExecutingAssembly().GetName().Version?.ToString(3) ?? "1.0.0";
    public static ToolSettings Settings = Storage.Read(Storage.FilePath("settings.json"), new ToolSettings());
    internal static HttpClient Http = new() { Timeout = TimeSpan.FromMinutes(10) };
    public static void Save() => Storage.Write(Storage.FilePath("settings.json"), Settings);
    public static UpdatePayload Verify(string json) { var envelope = JsonSerializer.Deserialize<SignedUpdate>(json, Storage.Json) ?? throw new Exception("Manifeste de mise à jour absent."); var bytes = Convert.FromBase64String(envelope.Payload); using var rsa = RSA.Create(); var resource = Assembly.GetExecutingAssembly().GetManifestResourceStream("CremaTools.UpdatePublicKey.pem") ?? throw new Exception("Clé de vérification absente."); using var reader = new StreamReader(resource); rsa.ImportFromPem(reader.ReadToEnd()); if (!rsa.VerifyData(bytes, Convert.FromBase64String(envelope.Signature), HashAlgorithmName.SHA256, RSASignaturePadding.Pss)) throw new Exception("La signature de la mise à jour n’est pas valide."); var manifest = JsonSerializer.Deserialize<UpdatePayload>(bytes) ?? throw new Exception("Version non valide."); if (!System.Version.TryParse(manifest.Version, out _) || manifest.Size <= 0 || manifest.Size > 500L * 1024 * 1024 || manifest.Sha256.Length != 64 || !Uri.TryCreate(manifest.Url, UriKind.Absolute, out var uri) || uri.Scheme != "https") throw new Exception("Informations de mise à jour non valides."); return manifest; }
    public static async Task<UpdatePayload?> Check(CancellationToken cancel) { if (!Uri.TryCreate(Settings.UpdateUrl, UriKind.Absolute, out var uri) || uri.Scheme != "https") throw new Exception("L’adresse de mise à jour doit utiliser HTTPS."); using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancel); timeout.CancelAfter(TimeSpan.FromSeconds(20)); var json = await Http.GetStringAsync(uri, timeout.Token); var manifest = Verify(json); Settings.LastCheck = DateTime.UtcNow; Save(); return System.Version.Parse(manifest.Version) > System.Version.Parse(Version) ? manifest : null; }
    public static async Task Download(UpdatePayload update, IProgress<string> progress, CancellationToken cancel) { string folder = Path.Combine(Storage.Root, "Updates"); Directory.CreateDirectory(folder); string file = Path.Combine(folder, "CremaTools-Setup-" + update.Version + ".exe"), partial = file + ".partial"; try { using var response = await Http.GetAsync(update.Url, HttpCompletionOption.ResponseHeadersRead, cancel); response.EnsureSuccessStatusCode(); using var input = await response.Content.ReadAsStreamAsync(cancel); using (var output = new FileStream(partial, FileMode.Create, FileAccess.Write, FileShare.None)) { var buffer = new byte[81920]; long written = 0; int n; while ((n = await input.ReadAsync(buffer, cancel)) > 0) { written += n; if (written > update.Size) throw new Exception("Téléchargement plus volumineux que prévu."); await output.WriteAsync(buffer.AsMemory(0, n), cancel); progress.Report($"Mise à jour : {written * 100 / update.Size} %"); } if (written != update.Size) throw new Exception("Téléchargement incomplet."); } using (var inputFile = File.OpenRead(partial)) { if (!Convert.ToHexString(await SHA256.HashDataAsync(inputFile, cancel)).Equals(update.Sha256, StringComparison.OrdinalIgnoreCase)) throw new Exception("Le contrôle de la mise à jour a échoué."); } File.Move(partial, file, true); Settings.PendingInstaller = file; Settings.PendingVersion = update.Version; Settings.PendingHash = update.Sha256; Save(); } catch { if (File.Exists(partial)) File.Delete(partial); throw; } }
    public static bool Ready => File.Exists(Settings.PendingInstaller) && System.Version.TryParse(Settings.PendingVersion, out var pending) && pending > System.Version.Parse(Version);
    public static void InstallPending() { if (!Ready) return; using (var file = File.OpenRead(Settings.PendingInstaller)) { if (!Convert.ToHexString(SHA256.HashData(file)).Equals(Settings.PendingHash, StringComparison.OrdinalIgnoreCase)) throw new Exception("L’installateur préparé a changé. Relancez la recherche."); } var info = new ProcessStartInfo(Settings.PendingInstaller) { UseShellExecute = true }; info.ArgumentList.Add("/S"); Process.Start(info); Settings.PendingInstaller = ""; Settings.PendingVersion = ""; Settings.PendingHash = ""; Save(); }
}
